import itertools

def check_coloring(grid, k):
    rows = len(grid)
    cols = len(grid[0])

    # I-polyominoes (horizontal)
    for r in range(rows):
        for c in range(cols - 2):
            if len({grid[r][c], grid[r][c+1], grid[r][c+2]}) < k:
                return False

    # I-polyominoes (vertical)
    for r in range(rows - 2):
        for c in range(cols):
            if len({grid[r][c], grid[r+1][c], grid[r+2][c]}) < k:
                return False

    # L-polyominoes
    # There are 4 orientations of L-polyominoes
    for r in range(rows - 1):
        for c in range(cols - 1):
            # L-shape 1: (r,c), (r+1,c), (r+1,c+1)
            if len({grid[r][c], grid[r+1][c], grid[r+1][c+1]}) < k:
                return False
            # L-shape 2: (r,c), (r,c+1), (r+1,c+1)
            if len({grid[r][c], grid[r][c+1], grid[r+1][c+1]}) < k:
                return False
            # L-shape 3: (r,c), (r,c+1), (r+1,c)
            if len({grid[r][c], grid[r][c+1], grid[r+1][c]}) < k:
                return False
            # L-shape 4: (r+1,c), (r,c+1), (r+1,c+1)
            if len({grid[r+1][c], grid[r][c+1], grid[r+1][c+1]}) < k:
                return False

    return True

def solve_k3():
    # Try all colorings for a small grid
    # For k=3, if no 3x3 coloring works, then C >= 3.
