import itertools

def get_polyominoes(area):
    # Generate all polyominoes of a given area
    # A polyomino is a set of (r, c) tuples
    polyominoes = []

    def get_neighbors(cells):
        neighbors = set()
        for r, c in cells:
            for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                neighbors.add((r + dr, c + dc))
        return neighbors - cells

    def generate(cells):
        if len(cells) == area:
            # Normalize
            min_r = min(r for r, c in cells)
            min_c = min(c for r, c in cells)
            normalized = tuple(sorted((r - min_r, c - min_c) for r, c in cells))
            polyominoes.append(normalized)
            return

        for neighbor in get_neighbors(cells):
            generate(cells | {neighbor})

    generate(frozenset([(0, 0)]))
    return list(set(polyominoes))

def check_coloring_C(grid, k, C, polyominoes):
    rows = len(grid)
    cols = len(grid[0])

    for poly in polyominoes:
        # We need to check every possible position of this polyomino in the grid
        # A polyomino's bounding box is (max_r - min_r + 1, max_c - min_c + 1)
        max_r = max(r for r, c in poly)
        max_c = max(c for r, c in poly)

        for r in range(rows - max_r):
            for c in range(cols - max_c):
                # Check if this polyomino at (r,c) uses < k colors
                colors = {grid[r+pr][c+pc] for pr, pc in poly}
                if len(colors) < k:
                    return False
    return True

def solve_C(k, C):
    polyominoes = get_polyominoes(C)
    # Use a small grid
    # For C=4, a 4x4 grid might be enough
    # 3^16 is too large. Let's use a 3x4 grid? 3^12 = 531,441.
    import itertools
    for coloring in itertools.product(range(k), repeat=12):
        grid = [coloring[0:4], coloring[4:8], coloring[8:12]]
        if check_coloring_C(grid, k, C, polyominoes):
            return True
    return False

